using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Identity;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Sem.Web.Core;
using Sem.Web.Data;
using Sem.Web.Runtime;
var root=Path.Combine(Path.GetTempPath(),"sem-public-answers-"+Guid.NewGuid());Directory.CreateDirectory(root);
var services=new ServiceCollection();services.AddLogging();services.AddDbContextFactory<ApplicationDbContext>(o=>o.UseSqlite("Data Source="+Path.Combine(root,"data.db")),ServiceLifetime.Scoped);services.AddIdentityCore<ApplicationUser>(o=>o.Stores.SchemaVersion=IdentitySchemaVersions.Version3).AddEntityFrameworkStores<ApplicationDbContext>();services.AddSingleton(TimeProvider.System);Microsoft.Extensions.DependencyInjection.DataProtectionServiceCollectionExtensions.AddDataProtection(services);services.AddSingleton<BusinessNotificationStore>();services.AddScoped<CoreFoundationService>();using var provider=services.BuildServiceProvider();using var scope=provider.CreateScope();var factory=scope.ServiceProvider.GetRequiredService<IDbContextFactory<ApplicationDbContext>>();var core=scope.ServiceProvider.GetRequiredService<CoreFoundationService>();int passed=0;
void Check(bool v,string label){if(!v)throw new Exception(label);passed++;Console.WriteLine("PASS "+label);}
async Task Deny(Func<Task> f,string label){bool denied=false;try{await f();}catch(UnauthorizedAccessException){denied=true;}Check(denied,label);}
ClaimsPrincipal Who(string id)=>new(new ClaimsIdentity([new Claim(ClaimTypes.NameIdentifier,id),new Claim("AspNet.Identity.SecurityStamp",id+"-stamp"),new Claim(PasskeyAdditionService.SessionClaim,id+"-session")],"Identity.Application"));
var admin=Who("admin");var member=Who("member");
async Task Change(string q,Action<EventQuestion> edit){await using var db=await factory.CreateDbContextAsync();edit(await db.EventQuestions.SingleAsync(x=>x.Id==q));await db.SaveChangesAsync();}
try{
 await using(var db=await factory.CreateDbContextAsync()){
  await SqliteStorageInitializer.InitializeAsync(db);
  foreach(var id in new[]{"admin","member","other","blank","disabled"})db.Users.Add(new(){Id=id,Email=id+"@PRIVATE.invalid",UserName=id+"@PRIVATE.invalid",DisplayName=id=="other"?"<script>alert(1)</script>":id,Enabled=id!="disabled",EmailConfirmed=true,SecurityStamp=id+"-stamp",IsAdmin=id=="admin"});
  var e=new SessionEvent{Id="event",Title="Public event",ScheduledDate="2099-01-01T00:00:00.000Z",CreatedAt="2026-10-01T00:00:00.000Z",ManualPhaseOverride=true,RowVersion=7};e.Phases.Add(new(){Id="view",EventId=e.Id,Kind="View",Name="閲覧",IsActive=true});e.Phases.Add(new(){Id="hidden",EventId=e.Id,Kind="Hidden",Name="非表示",IsActive=false});db.SessionEvents.Add(e);
  db.EventQuestions.AddRange(new EventQuestion{Id="yes",EventId=e.Id,Text="Yes?",Type="YesNo",Public=true},new EventQuestion{Id="text",EventId=e.Id,Text="Text?",Type="Text",Public=true,SortOrder=1},new EventQuestion{Id="private",EventId=e.Id,Text="SECRET QUESTION",Type="Text",Public=false,PublicText=false,SortOrder=2},new EventQuestion{Id="stopped",EventId=e.Id,Text="STOPPED",Type="Text",Public=true,PublicText=true,Disabled=true},new EventQuestion{Id="deleted",EventId=e.Id,Text="DELETED",Type="Text",Public=true,DeletedAt=e.CreatedAt},new EventQuestion{Id="empty",EventId=e.Id,Text="Empty",Type="YesNo",Public=true,SortOrder=3});
  foreach(var (q,u,v) in new (string,string,string?)[]{("yes","member","YES"),("yes","other","\u3000NO\u00a0"),("yes","blank","invalid"),("yes","disabled",null),("text","member"," secret-body "),("text","other","secret-body"),("text","blank"," \t \u3000\u0085"),("text","disabled","SECRET-DISABLED"),("private","member","PRIVATE-CONTENT"),("stopped","member","STOPPED-CONTENT"),("deleted","member","DELETED-CONTENT")})db.EventQuestionAnswers.Add(new(){QuestionId=q,UserId=u,Value=v,UpdatedAt=e.CreatedAt});
  await db.SaveChangesAsync();
 }
 await Deny(()=>core.ReadPublicAnswersAsync(new ClaimsPrincipal(),"event"),"Anonymous denied");await Deny(()=>core.ReadPublicAnswersAsync(Who("disabled"),"event"),"Disabled actor denied");await Deny(()=>core.ReadPublicAnswersAsync(member,"missing"),"Unknown event denied");
 var p=await core.ReadPublicAnswersAsync(member,"event");Check(p.Title=="Public event"&&p.RowVersion==7,"Correct event snapshot metadata");Check(p.Questions.Select(x=>x.Id).SequenceEqual(new[]{"yes","text","empty"}),"Only active public questions in configured order");
 var yes=p.Questions[0];Check(yes.AnsweredCount==2,"YesNo denominator excludes null and invalid values");Check(yes.Groups.Select(x=>x.Value).SequenceEqual(new[]{"YES","NO"})&&yes.Groups.All(x=>x.Count==1),"YES and NO explicit stable groups");Check(yes.Groups[1].Respondents.Single().UserId=="other","Trimmed NO retains correct respondent");
 var text=p.Questions[1];Check(text.AnsweredCount==3,"Saved nonblank answers include retained inactive users and nonparticipants");Check(!text.PublicText&&text.Groups.Length==1&&text.Groups[0].Value is null,"Private text is a single body-free answered group");Check(text.Groups[0].Count==3&&text.Groups[0].Respondents.Length==3,"Private-text counts match respondent set");var json=JsonSerializer.Serialize(p);Check(!json.Contains("secret-body")&&!json.Contains("SECRET-DISABLED"),"No private answer content in public DTO");Check(!json.Contains("PRIVATE-CONTENT")&&!json.Contains("SECRET QUESTION")&&!json.Contains("STOPPED-CONTENT")&&!json.Contains("DELETED-CONTENT"),"Private disabled and deleted questions absent");Check(!json.Contains("PRIVATE.invalid")&&!json.Contains("SecurityStamp")&&!json.Contains("UpdatedAt"),"No email authentication or answer timestamps exposed");Check(p.Questions[2].AnsweredCount==0&&p.Questions[2].Groups.All(x=>x.Count==0&&x.Respondents.Length==0),"Empty YesNo has explicit zero groups");Check(yes.Groups[1].Respondents.Single().DisplayName=="<script>alert(1)</script>","Display names retained as data not HTML");
 Check(JsonSerializer.Serialize(await core.ReadPublicAnswersAsync(admin,"event"))==json,"Admin has no private-answer bypass on public surface");
 await Change("text",q=>q.PublicText=true);p=await core.ReadPublicAnswersAsync(member,"event");text=p.Questions.Single(x=>x.Id=="text");Check(text.PublicText&&text.Groups.Length==2,"Explicit public text groups by trimmed exact content");Check(text.Groups.Single(x=>x.Value=="secret-body").Count==2,"Equal trimmed values counted together");Check(text.Groups.Sum(x=>x.Count)==text.AnsweredCount,"Group totals equal answered denominator");
 await using(var db=await factory.CreateDbContextAsync()){var a=await db.EventQuestionAnswers.SingleAsync(x=>x.QuestionId=="text"&&x.UserId=="other");a.Value="Secret-body";await db.SaveChangesAsync();}p=await core.ReadPublicAnswersAsync(member,"event");Check(p.Questions.Single(x=>x.Id=="text").Groups.Length==3,"Case differences remain distinct, no invented normalization");
 await Change("text",q=>q.PublicText=false);p=await core.ReadPublicAnswersAsync(member,"event");Check(!JsonSerializer.Serialize(p).Contains("secret-body")&&p.Questions.Single(x=>x.Id=="text").Groups.Single().Value is null,"Revoking body permission takes effect on next read");
 await Change("text",q=>{q.Public=false;q.PublicText=false;});Check(!(await core.ReadPublicAnswersAsync(admin,"event")).Questions.Any(x=>x.Id=="text"),"Public=false blocks private text even for admin");await Change("yes",q=>q.Disabled=true);Check(!(await core.ReadPublicAnswersAsync(member,"event")).Questions.Any(x=>x.Id=="yes"),"Disabled question disappears immediately");
 await using(var db=await factory.CreateDbContextAsync()){var e=await db.SessionEvents.Include(x=>x.Phases).SingleAsync();foreach(var ph in e.Phases)ph.IsActive=false;await db.SaveChangesAsync();e.Phases.Single(x=>x.Kind=="Hidden").IsActive=true;await db.SaveChangesAsync();}await Deny(()=>core.ReadPublicAnswersAsync(member,"event"),"Current Hidden phase blocks ordinary viewer");Check((await core.ReadPublicAnswersAsync(admin,"event")).Questions.All(x=>x.Id=="empty"),"Hidden manager preview still honors all question privacy flags");
 await using(var db=await factory.CreateDbContextAsync()){var e=await db.SessionEvents.Include(x=>x.Phases).SingleAsync();foreach(var ph in e.Phases)ph.IsActive=false;await db.SaveChangesAsync();e.Phases.Single(x=>x.Kind=="View").IsActive=true;e.ManualPhaseOverride=false;await db.SaveChangesAsync();}await Deny(()=>core.ReadPublicAnswersAsync(member,"event"),"Automatic future Hidden phase evaluated instead of stale active flag");
 await using(var db=await factory.CreateDbContextAsync()){var e=await db.SessionEvents.SingleAsync();e.ManualPhaseOverride=true;db.RevokedAuthSessions.Add(new(){TokenHash=SemEndpoints.Hash("member-session"),UserId="member",RevokedAt=e.CreatedAt});await db.SaveChangesAsync();}await Deny(()=>core.ReadPublicAnswersAsync(member,"event"),"Revoked session cannot retrieve cached summary");
 await using(var db=await factory.CreateDbContextAsync()){var u=await db.Users.SingleAsync(x=>x.Id=="admin");u.SecurityStamp="changed";await db.SaveChangesAsync();}await Deny(()=>core.ReadPublicAnswersAsync(admin,"event"),"Changed security stamp denied");
 await using(var db=await factory.CreateDbContextAsync()){Check(await db.EventQuestionAnswers.CountAsync()==11,"Reads preserve all original answers");Check(await db.EventSpectators.CountAsync()==0&&await db.SongParts.CountAsync()==0,"Summaries do not invent or require participation");Check(!db.Database.HasPendingModelChanges(),"No database migration needed or pending model changes");await SqliteStorageInitializer.InitializeAsync(db);Check(await db.EventQuestionAnswers.CountAsync()==11,"Restart preserves stored private and public answers");}
 Console.WriteLine("Public answer checks passed: "+passed);
}finally{SqliteConnection.ClearAllPools();Directory.Delete(root,true);}
